                   .tuning-in {
                       flex: 1;
                       display: flex;
                       align-items: center;
                       justify-content: center;
                       color: white;
                       font-family: Arial, sans-serif;
                       font-size: 1.2rem;
                       margin: 0;
                       min-height: 24px;
                       width: 101px;
                       animation: enter 560ms cubic-bezier(0.81, 0.24, 0.48, 0.85) forwards;
                   }
                   .tuning-in::after {
                       content: '';
                       display: inline-block;
                       width: 30px;
                       inset-inline-start: 0;
                       animation: dotting 1.0s steps(3, end) infinite;
                   }
                   .config-json-spinner {
                       animation: 1s linear infinite spin;
                   }
                   .config-json-spinner span svg {
                       height: 28px;
                       width: 28px;
                   }
                   @keyframes dotting {
                       0% { content: ''; }
                       25% { content: '.'; }
                       50% { content: '..'; }
                       75% { content: '...'; }
                       100% { content: ''; }
                   }
                   @keyframes enter {
                       0% { opacity: 0; }
                       100% { opacity: 1; }
                   }
                   @keyframes spin {
                       0% { transform: rotate(0deg) }
                       100% { transform: rotate(360deg) }
                   }















